export const campusMapImage='./assets/campus-base-v3-20261111.png';
export function addCampusBrand(map,{regions=true}={}){const base=map.querySelector('img');if(base)applyCampusBase(base);const slope=document.createElement('img');slope.src='./assets/campus-slope-overlay.svg';slope.alt='右側斜坡通往後門道路（示意）';slope.className='campus-slope-layer';slope.style.cssText='position:absolute;inset:0;width:100%;height:100%;pointer-events:none';map.append(slope);const compass=document.createElement('span');compass.className='map-north map-north-large';compass.setAttribute('role','img');compass.setAttribute('aria-label','北朝左下方，指向前門方向');compass.innerHTML='北<span aria-hidden="true">↙</span><small>前門方向</small>';map.append(compass);if(regions)mountRegionLayer(map);}
let published;
export function loadRegions(){return published ||= fetch('./campus-regions.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('區域圖層載入失敗');return r.json()});}
export function drawRegions(layer,data){layer.replaceChildren();for(const r of data.regions){const label=document.createElement('span');label.textContent=r.name;label.dataset.region=r.id;label.style.cssText=`position:absolute;left:${r.x}%;top:${r.y}%;transform:translate(-50%,-50%);background:#fffffff0;border:1px solid #315b43;border-radius:6px;padding:3px 6px;font:clamp(9px,1vw,14px) system-ui;color:#173f32;white-space:nowrap`;layer.append(label);}}
export async function mountRegionLayer(map){const layer=document.createElement('div');layer.className='campus-region-layer';layer.style.cssText='position:absolute;inset:0;pointer-events:none';map.insertBefore(layer,map.querySelector('#route,#pins,#space-pins,.campus-station-layer'));try{drawRegions(layer,await loadRegions());}catch{layer.textContent='區域名稱載入失敗，請重新整理';}}

let baseConfig;
export function loadCampusBase(){return baseConfig ||= fetch('./campus-base.json',{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('俯視底圖設定載入失敗');return r.json()});}
export async function applyCampusBase(image){try{const config=await loadCampusBase();if(image.getAttribute('src')===campusMapImage)image.src=config.url;}catch{}}
